import json,math,statistics
from pathlib import Path
P=Path(__file__).resolve().parent

def mean_sd(v):return (statistics.mean(v),statistics.stdev(v) if len(v)>1 else 0.)
def main():
    r=json.loads((P/'results.json').read_text());checks=json.loads((P/'correctness.json').read_text());frozen=json.loads((P/'protocol_frozen.json').read_text())
    summary={'complete':r['complete'],'correctness_passed':checks['passed'],'quality':{},'paired':{},'memory':[]}
    lines=['# Reversible Transformer pilot','',f"Complete training protocol: {r['complete']}. Correctness gates passed: {checks['passed']}.",'','This is a tiny, fixed-protocol CPU byte-language study. It tests hidden-state inversion, backpropagation equivalence, memory diagnostics and held-out prediction. It is not an inverse from generated tokens to prompts and does not measure general intelligence.','', '## Held-out results','', 'All metrics below are byte cross entropy converted to bits per byte; lower is better. Three fixed seeds; final checkpoints, no test/validation selection.']
    for endpoint in ('equal_data','equal_cpu'):
        lines+=['',f'### {endpoint}','', '| Arm | Runs | WikiText test BPB mean ± sample SD | FineWeb BPB mean ± sample SD | Mean updates | Mean training CPU sec |','|---|---:|---:|---:|---:|---:|']
        summary['quality'][endpoint]={}
        for mode in ('ordinary','reversible_graph','reversible_inverse'):
            rows=[row for row in r['runs'] if row['mode']==mode and endpoint in row]
            if not rows:continue
            vals={split:[row[endpoint]['metrics'][split]['bits_per_byte'] for row in rows] for split in ('validation','test','fineweb')};stats={s:{'mean':mean_sd(v)[0],'sample_sd':mean_sd(v)[1],'per_seed':dict(zip([row['seed'] for row in rows],v))} for s,v in vals.items()}
            stats.update(runs=len(rows),mean_updates=statistics.mean(row[endpoint]['updates'] for row in rows),mean_train_cpu_seconds=statistics.mean(row[endpoint]['train_cpu_seconds'] for row in rows));summary['quality'][endpoint][mode]=stats
            lines.append(f"| {mode} | {len(rows)} | {stats['test']['mean']:.5f} ± {stats['test']['sample_sd']:.5f} | {stats['fineweb']['mean']:.5f} ± {stats['fineweb']['sample_sd']:.5f} | {stats['mean_updates']:.1f} | {stats['mean_train_cpu_seconds']:.3f} |")
        for a,b in [('reversible_graph','ordinary'),('reversible_inverse','reversible_graph')]:
            ar={row['seed']:row for row in r['runs'] if row['mode']==a and endpoint in row};br={row['seed']:row for row in r['runs'] if row['mode']==b and endpoint in row};pairs={s:ar[s][endpoint]['metrics']['test']['bits_per_byte']-br[s][endpoint]['metrics']['test']['bits_per_byte'] for s in sorted(ar.keys()&br.keys())}
            if pairs:
                mean,sd=mean_sd(list(pairs.values()));key=f'{endpoint}:{a}-{b}';summary['paired'][key]={'per_seed':pairs,'mean_bpb_difference':mean,'sample_sd':sd};lines+=['',f'Paired test difference {a} minus {b}: {mean:+.6f} BPB (seed differences: '+', '.join(f'{s}: {v:+.6f}' for s,v in pairs.items())+'). Negative favors the first arm.']
    lines+=['','## Learning sanity check','', '| Seed | Arm | Initial test BPB | Equal-data test BPB |','|---|---|---:|---:|']
    for row in sorted(r['runs'],key=lambda row:(row['seed'],row['mode'])):lines.append(f"| {row['seed']} | {row['mode']} | {row['initial']['test']['bits_per_byte']:.5f} | {row['equal_data']['metrics']['test']['bits_per_byte']:.5f} |")
    lines+=['','## Reconstruction and gradient parity','', '| Dtype | Depth | Inverse(forward) max abs | Forward(inverse) max abs | All gradient relative L2 |','|---|---:|---:|---:|---:|']
    for row in checks['stack']:lines.append(f"| {row['dtype']} | {row['depth']} | {row['inverse_forward']['max_abs']:.3g} | {row['forward_inverse']['max_abs']:.3g} | {row['all_input_parameter_gradients']['relative_l2']:.3g} |")
    lines+=['','The tied embedding/readout end-to-end model also passed paired logits and all-parameter gradient checks at initialization and after five AdamW updates. Future-input perturbations caused exactly zero changes to earlier logits. Float errors are measured, not described as bit-exact.','', '## Memory and execution diagnostic','', '| Arm | Depth | Retained forward nonparameter MiB | Whole-process peak RSS MiB | Median update CPU ms |','|---|---:|---:|---:|---:|']
    for p in sorted(P.glob('memory_*.json')):
        row=json.loads(p.read_text());summary['memory'].append(row);lines.append(f"| {row['mode']} | {row['depth']} | {row['retained_forward_nonparameter_storage_bytes']/2**20:.3f} | {row['whole_process_peak_rss_bytes']/2**20:.2f} | {1000*statistics.median(t['cpu_seconds'] for t in row['timings']):.3f} |")
    lines+=['','Saved tensors are retained forward graph storage, not whole-step peak memory. The inverse method temporarily stores each recomputed block during backward. Whole-process RSS includes Python/Torch, model, gradients, optimizer and allocator behavior. These CPU results do not establish GPU speed or memory savings.','', '## Matching and limits','', '- All arms have identical parameter names and tensor dimensions; actual counts are in correctness.json. Ordinary state width48 differs from two48-wide reversible streams. Embedding duplication and average readout are not bijective.','- Every block has the same forward attention/MLP matrix shapes. Inverse-based differentiation recomputes those functions; equal data is not equal FLOPs. Equal-CPU continuations use more training data when faster and are reported separately.','- Training CPU includes batch sampling, forward/backward, clipping and optimizer. Evaluation/IO/imports are excluded from that metric but included in the execution receipt cap. Shared-runtime interference can affect time comparisons.','- Context64, byte vocabulary256, four small layers, only256000 target-byte exposures at the equal-data endpoint. This is a bounded pilot, not frontier-scale evidence.','- Official WikiText splits are disjoint by dataset construction; exact selected-window overlap is recorded below. That is not broad semantic decontamination. Prior user research has already used this benchmark family.','- FineWeb is out-of-domain frozen evaluation only,100 preselected documents. No corpus text is redistributed.','- Three seeds do not justify strong statistical or generalization claims. No sample-quality or intelligence score is inferred from NLL.','- No scaling proposal to600B follows from this test. Robust larger-scale replication, longer contexts, GPU profiles, mixed-precision stability, downstream tasks and competitive tuned controls would be required.','', '## Data provenance and overlap','',f"WikiText revision: {frozen['source_manifests']['wikitext_manifest.json']['revision']}. License verified via Hugging Face card: CC-BY-SA3.0 / GFDL tags. Source byte hashes and frozen selections are in protocol_frozen.json."]
    for split,meta in frozen['eval_meta'].items():lines.append(f"- {split}: {meta['windows']} windows, {meta['scored_bytes']} scored bytes, {meta['documents']} documents; {meta['identical_full_windows_in_train']} exact full-window matches in training, {meta['duplicate_selected_windows']} duplicate selected windows.")
    lines+=['','## Reproduction','', 'Use an existing official/reputable CPU PyTorch2.6 runtime. Run checks.py, study.py freeze, each memory_probe.py arm/depth, then study.py run and report.py. launch.py enforces the local queue flag, advisory locks and global CPU/wall/RSS caps. Do not use its timing-slot flag without explicit scheduling clearance. Original corpus bytes are not bundled; download the pinned official sources using the provenance manifests.','', 'Read INVERSE_ATLAS.md for the operation-level mathematics, assumptions and prior art.']
    (P/'REPORT.md').write_text('\n'.join(lines)+'\n');(P/'summary.json').write_text(json.dumps(summary,indent=2)+'\n');print('Wrote REPORT.md and summary.json')
if __name__=='__main__':main()
